#!/usr/bin/env Rscript
if (!requireNamespace("ape", quietly=TRUE) || !requireNamespace("pkgload", quietly=TRUE)) stop("needs ape/pkgload")
out <- "docs/dev-log/evidence/ou-v1-r5"; dir.create(out, recursive=TRUE, showWarnings=FALSE); pkgload::load_all(".", compile=TRUE, quiet=TRUE)
set.seed(2026091701); tree<-ape::rcoal(128);tree$tip.label<-sprintf("sp%03d",1:128);tree$edge.length<-tree$edge.length/max(ape::node.depth.edgelength(tree)[1:128]);d<-ape::cophenetic.phylo(tree);u<-drop(t(chol(.45^2*exp(-.7*d)))%*%rnorm(128));sp<-rep(tree$tip.label,each=12);dat<-data.frame(y=u[match(sp,tree$tip.label)]+rnorm(length(sp),sd=exp(-1)),species=sp)
fit_one <- function(alpha = NULL) { tree_local<-tree; f<-if(is.null(alpha)) bf(y~phylo(1|species,tree=tree_local),sigma~1) else bf(y~phylo(1|species,tree=tree_local,model="ou"),sigma~1); ctl<-drmTMB:::drm_parse_control(drm_control(optimizer=list(eval.max=1500,iter.max=1500))); z<-drmTMB:::drm_build_gaussian_ls_spec(f,dat,env=environment(),weights=NULL,control=ctl,impute=NULL,missing=drmTMB:::drm_parse_missing_control(miss_control())); if(!is.null(alpha)){z$map$log_decay_phylo<-factor(NA);z$start$log_decay_phylo<-log(alpha)}; t0<-proc.time()[["elapsed"]]; fit<-drmTMB:::drm_fit_spec(z,f,gaussian(),ctl,REML=FALSE,penalty=NULL,estimator="ml"); data.frame(model=if(is.null(alpha))"bm" else "ou_fixed",alpha_assumed=if(is.null(alpha))NA_real_ else alpha,objective=fit$opt$objective,AIC=stats::AIC(fit),mu_intercept=unname(fit$par$mu[[1]]),sigma_intercept=unname(fit$par$sigma[[1]]),convergence=fit$opt$convergence,pdHess=isTRUE(fit$sdr$pdHess),elapsed_seconds=proc.time()[["elapsed"]]-t0) }
grid<-c(.1,.3,.7,1.3,2.5); ans<-do.call(rbind,c(list(fit_one()),lapply(grid,fit_one))); utils::write.csv(ans,file.path(out,"sensitivity.csv"),row.names=FALSE);ape::write.tree(tree,file.path(out,"tree.nwk"));utils::write.csv(dat,file.path(out,"data.csv"),row.names=FALSE);cat("OU_V1_R5_PASS\n")
